import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"47、【困】 坎下兌上","description":"周易尚氏學 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"周易尚氏學 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/shangshi/052.md","filePath":"classics/shangshi/052.md"}'),s={name:"classics/shangshi/052.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><p>二五剛得中。處險能說。故亨。貞佔也。二五為大人。故貞大人吉也。兌口為言。三至上正反兌。所向不同。故有言不信。此其義始見於左傳。左傳昭五年明夷之謙曰。於人為言。敗言為讒。謂謙上震為人為言。下艮為反震。故曰敗言。是以正反震為讒。易林承其義。於訟之困雲。心與言反。正釋此語也。坤之離雲。齊魯爭言。離二至五正反兌。故曰爭言。爭言即不信。離二至五。與困三至上同也。舊解皆誤。詳焦氏易詁。</p><p>彖曰。困。剛b也。險以說。困而不失其所亨。其唯君子乎。貞大人吉。以剛中也。有言不信。尚口乃窮也。</p><p>坎剛b。三至上剛b。陽陷陰中故困。因而不失其所亨。唯君子能之。君子即大人。若小人即不堪矣。兌為口。三至上正反兌。故曰尚口。尚口乃窮者。言徒尚口說。必有相反而不信者。故窮也。</p><p>象曰。澤無水。困。君子以致命遂志。</p><p>水在澤下。則澤竭矣。故曰無水。巽為命。而兌為反巽。為毀折。故曰致命。坎為志。二人於淵不出。故曰遂志。學易之君子以之。</p><p>初六。臀困於株木。入於幽谷。三歲不覿。 兇。</p><p>初在下。故曰臀。與夬九四同。株木謂坎。言初欲應四。坎陷為阻。故困於株木。株乾也。韓非子守株待兔。而坎為棟。故為株木。坎為幽。坎陷為谷。初在下。故人於幽谷。離伏故不覿。三歲言其久。蓋初失位。處坎下。故其象如此。茹敦和以坎為三歲。王昭素謂初至三三爻為三歲。以坎上六證之。茹說是也。</p><h3 id="象曰。入於幽谷。幽不明也" tabindex="-1">象曰。入於幽谷。幽不明也 <a class="header-anchor" href="#象曰。入於幽谷。幽不明也" aria-label="Permalink to “象曰。入於幽谷。幽不明也”">​</a></h3><p>離伏坎夜。故幽不明。</p><p>九二。困於酒食。朱紱方來。利用亨祀。徵兇。無咎。</p><p>坎為酒食。需九五需於酒食是也。二居坎中。故困於酒食。巽為繩為級。坎為赤。巽在二前。故日朱龍（左言）方來。言將膺錫命也。博雅紱綬也。朱級貴人所服。以祭宗廟者。故用以亨祀則利也。然五不應故徵兇。得中亦無咎。</p><h3 id="象曰。困於酒食。中有慶也。" tabindex="-1">象曰。困於酒食。中有慶也。 <a class="header-anchor" href="#象曰。困於酒食。中有慶也。" aria-label="Permalink to “象曰。困於酒食。中有慶也。”">​</a></h3><p>居陰中。故有慶。</p><p>六三。困於石。據於蒺藜 入於其宮。不見其妻。兇。</p><p>巽為石。坎為蒺藜。三前臨巽。故困於石。下據坎。故據於蒺藜。石堅剛不可人。蒺藜刺人。不可踐也。巽為人。坎為宮。故人於其官。巽為齊。妻者齊也。故巽為妻。巽為伏。又上無應。故人宮而不見妻也。象而如是。兇可知也。巽石象。宋邵雍用之。後儒怪駭。豈知焦氏易林。同人之小畜雲。戴石上山。步跌不前。小畜小巽為石。下乾為山為首。石在首上。故曰戴石。餘證尚多。詳焦氏易詁卷一。</p><h3 id="象曰。據於蒺藜。乘剛也。入於其宮。不見其妻。不詳也。" tabindex="-1">象曰。據於蒺藜。乘剛也。入於其宮。不見其妻。不詳也。 <a class="header-anchor" href="#象曰。據於蒺藜。乘剛也。入於其宮。不見其妻。不詳也。" aria-label="Permalink to “象曰。據於蒺藜。乘剛也。入於其宮。不見其妻。不詳也。”">​</a></h3><p>釋文雲。蒺藜茨草。虞翻謂為木名似非。釋估茨蒺藜。注布地蔓生。有子。三角刺人。詩庸（右邑）風。牆有茨。傳茨蒺藜。孔疏蒺有刺。不可踐者是也。惟不可踐。故以喻乘剛。若為木則不合矣。正義作藜。然爾雅及毛詩傳皆作藜。藜藜通用。阮校必謂藜是。似亦無確證。詳善也。</p><p>九四。來徐徐。困於金車。吝。有終。</p><p>來應初為二所阻。故曰徐徐。二坎為車。離色黃外堅。故曰金車。困於金車。申來徐徐之故也。仍陰於險。不得應初也。然與初為正應。初吝終合。故曰有終。</p><h3 id="象曰。來徐徐。志在下也。雖不當位。有與也。" tabindex="-1">象曰。來徐徐。志在下也。雖不當位。有與也。 <a class="header-anchor" href="#象曰。來徐徐。志在下也。雖不當位。有與也。" aria-label="Permalink to “象曰。來徐徐。志在下也。雖不當位。有與也。”">​</a></h3><p>坎為志。志在下。言應初。</p><p>九五。劓刖。 困於赤紱。乃徐有說。利用祭祀。</p><p>艮伏鼻不見。故曰劓。兌折震足象毀。故曰別。坎為赤。巽為紱。故曰赤紱。乃二爻坎為不應。故困於赤紱。上遇陰利往。故有說。兌為食。故利用祭祀。</p><h3 id="象曰。劓刖。-志未得也。乃徐有說。以中直也。利用祭祀。受福也。" tabindex="-1">象曰。劓刖。 志未得也。乃徐有說。以中直也。利用祭祀。受福也。 <a class="header-anchor" href="#象曰。劓刖。-志未得也。乃徐有說。以中直也。利用祭祀。受福也。" aria-label="Permalink to “象曰。劓刖。 志未得也。乃徐有說。以中直也。利用祭祀。受福也。”">​</a></h3><p>坎為志。二無應。故志未得。坎五曰受福。茲與之同。傳所謂祭則受福也。</p><p>上六。困於葛藟，於臲卼，曰動悔。有悔，徵吉。</p><p>巽為葛c 。三至上正反巽。而三不應上。故困於葛cd e ？危險不安之貌。上乘剛。元應。故有是象。兌為口。曰者自警也。言處此d e ？之境。時時以動海有悔自警。動海者言動而應三。三不應故侮。有悔者言下乘陽又有悔也。徵吉謂三。言三往四。上得陽應而吉也。此二句向天的解。姑測其義如是。</p><h3 id="象曰。困於葛藟-未當也。動悔有悔-吉行也。" tabindex="-1">象曰。困於葛藟，未當也。動悔有悔，吉行也。 <a class="header-anchor" href="#象曰。困於葛藟-未當也。動悔有悔-吉行也。" aria-label="Permalink to “象曰。困於葛藟，未當也。動悔有悔，吉行也。”">​</a></h3><p>未當者。言上不宜乘陽也。吉行者。三之四上得陽應。故吉也。</p>',30)])])}const b=e(s,[["render",t]]);export{_ as __pageData,b as default};
